// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2006, "4-5", [{"author":"К. Кноп","question":"Один из месяцев года на белорусском языке называется «студзень». Это","choices":["сентябрь","май","август","апрель","январь."],"key":"Д","review":["Белорусский месяц","Сравни начало «студзень» с русскими словами «стужа», «студёный». Название подсказывает сильный холод.","Из предложенных месяцев зимний только январь. На январь и указывает белорусское название «студзень»."]},{"author":"Б. Иомдин","question":"Какой знак препинания не существует?","choices":["точка","точка с запятой","двоеточие","троеточие","многоточие."],"key":"Г","review":["Как называется знак?","Представь каждый знак. Есть точка, точка с запятой и двоеточие из двух точек друг над другом.","Три точки подряд в русском письме называются «многоточие». Знака с отдельным названием «троеточие» нет."]},{"author":"Е. Муравенко","question":"В какой из пар слова по смыслу связаны между собой не так, как в остальных парах?","choices":["<em>однофамилец — однофамилица</em>","<em>владелец — владелица</em>","<em>красавец — красавица</em>","<em>кузнец — кузница</em>","<em>певец — певица</em>."],"key":"Г","review":["Кого называют словами пары?","В парах «однофамилец — однофамилица», «владелец — владелица», «красавец — красавица» и «певец — певица» названы мужчина и женщина.","Кузнец — человек, а кузница — мастерская, где он работает. Значит, эта пара построена по другой связи."]},{"author":"Е. Муравенко","question":"Какое из этих существительных не того рода, что остальные?","choices":["<em>муравьишка</em>","<em>зайчишка</em>","<em>скворушка</em>","<em>соловушка</em>","<em>коровушка.</em>"],"key":"Д","review":["Род ласковых слов","Подставь «этот» или «эта», а не суди по последней букве. Говорят «этот муравьишка», «этот зайчишка», «этот скворушка», «этот соловушка».","«Эта коровушка» согласуется с «эта», как и слово «корова». Только это существительное женского рода."]},{"author":"Б. Иомдин","question":"Даны слова: <em>пирожки, рожки, ножки, снежки</em>. Сколько из них можно прочесть с ударением на последний слог, не сделав ошибки?","choices":["ни одно","одно","два","три","все."],"key":"Г","review":["Ударение на конце","Прочитай «купить пирожки́», «сварить рожки́» и «бросать снежки́». Все три допускают ударение на последнем слоге.","«Но́жки» произносятся с первым ударным слогом, например «но́жки стула». На конце ударение возможно в трёх словах."]},{"author":"Е. Муравенко","question":"В какой из пар оба слова могут называть один и тот же предмет?","choices":["<em>ком — комик</em>","<em>куль — кулик</em>","<em>пар — парик</em>","<em>кот — котик</em>","<em>перс — персик</em>."],"key":"Г","review":["Один предмет для пары","Проверь, действительно ли короткое слово можно назвать ласково словом с -ик. Комик, кулик и парик обозначают совсем другое, чем ком, куль и пар.","Одного кота можно назвать «котик». «Персик» же означает плод, а «перс» — человека. Подходит пара «кот — котик»."]},{"author":"И. Иткин и Е. Холодова","question":"С исторической точки зрения русское слово <em>вар</em>...<em>жка</em> образовано от слова <em>варяг</em> и буквально значит ‘варяжская рукавица’. А как правильно писать это слово?","choices":["<em>варяжка</em>","<em>варежка</em>","<em>варюжка</em>","<em>варижка</em>","<em>варьюжка</em>."],"key":"Б","review":["Как пишется «вар…жка»?","По происхождению слово связано с варягами, но древнее родство не всегда подсказывает современное написание.","В современном орфографическом словаре рукавица называется «варежка», через е. Такое написание нужно запомнить."]},{"author":"Е. Ренковская","question":"Вот пять слов. Какое из них отличается от других по составу?","choices":["<em>журналист</em>","<em>танкист</em>","<em>машинист</em>","<em>трубочист</em>","<em>гитарист</em>."],"key":"Г","review":["Пять слов на -ист","Сравни «журнал — журналист», «танк — танкист», «машина — машинист», «гитара — гитарист». В этих словах -ист называет человека по профессии или занятию.","Трубочист чистит трубы. Здесь соединены два корня — «труб-» и «-чист-», поэтому последние три буквы входят в корень."]},{"author":"М. Кронгауз","question":"Житель Киева называется:","choices":["<em>киевич</em>","<em>киевлянин</em>","<em>киевчанин</em>","<em>киевец</em>","<em>киевяк</em>."],"key":"Б","review":["Название жителя Киева","У названий жителей разных городов бывают разные окончания. Вспомни множественную форму «киевляне».","Один человек из Киева — «киевлянин». Слово с -янин сопоставляется с «киевляне», как «горожанин» с «горожане»."]},{"author":"Е. Муравенко","question":"В четырёх ребусах зашифрованы названия городов, в которых есть победители «Медвежонка», а в одном – название страны. В каком?","choices":["[МОСКВА]","[КИРОВ]","[ВОЛГОГРАД]","[МУРМАНСК]","[УКРАИНА]."],"key":"Д","review":["Города и страна в ребусах","В последнем ребусе стоит У, затем «кран» без последней н и «шина» без первой ш. Соедини У, «кра» и «ина».","Выходит «Украина» — название страны. Москва, Киров, Волгоград и Мурманск, зашифрованные в остальных рисунках, — города."],"figure":{"options":[{"src":"assets/medvezhonok/2006/4-5-10-1.svg","width":270,"height":154,"description":"Мост с запятой после него и К внутри А"},{"src":"assets/medvezhonok/2006/4-5-10-2.svg","width":281,"height":138,"description":"Кит с заменой Т на Р, затем ковш с запятыми по обе стороны"},{"src":"assets/medvezhonok/2006/4-5-10-3.svg","width":265,"height":144,"description":"Л внутри О, над горой буква Г между цифрами 2 и 3, затем Д"},{"src":"assets/medvezhonok/2006/4-5-10-4.svg","width":273,"height":138,"description":"Муха с двумя запятыми после неё, рама с зачёркнутой цифрой 2, носки с зачёркнутой О и запятой после них"},{"src":"assets/medvezhonok/2006/4-5-10-5.svg","width":352,"height":147,"description":"Буква У, кран с запятой после него, шина с запятой перед ней"}],"onlyPictures":true}},{"author":"И. Рубанов","question":"Саша написал: «<em>Мы будем рассматривать только хутьшие варианты</em>».\nА как надо было написать?","choices":["так и надо было","<em>мы будем рассматривать только хутшие варианты</em>","<em>мы будем рассматривать только худшие варианты</em>","<em>мы будем рассматривать только худьшие варианты</em>","<em>мы будем рассматривать только хучшие варианты</em>."],"key":"В","review":["Запись Саши","Сравни «лучшие» и «худшие», а затем найди родственное слово с хорошо слышимой д: «худой».","Пишем «худшие». Несмотря на то что перед ш звук д оглушается, буква д остаётся, а ь перед ш не требуется."]},{"author":"Е. Муравенко","question":"Форма множественного числа от четырёх существительных образована обычным образом, а от одного — с некоторыми особенностями. Что это за форма?","choices":["<em>цветы</em>","<em>кусты</em>","<em>открытки</em>","<em>места</em>","<em>моря</em>."],"key":"А","review":["Как образуется множество","Поставь формы в единственное число: кусты — куст, открытки — открытка, места — место, моря — море. В этих парах меняются окончания.","Один цветок, а много цветов — «цветы». При этом исчезает часть -ок. Форма «цвета» от слова «цвет» обычно обозначает разные окраски."]},{"author":"Б. Иомдин","question":"<em>За пазухой</em> — это где?","choices":["на груди под одеждой","за спиной под одеждой","в кармане","за поясом","за обшлагом рукава."],"key":"А","review":["Что спрятано за пазухой?","Представь, куда кладут вещь, чтобы прижать её к груди и прикрыть верхней частью рубашки или куртки.","Это место называется пазухой. «За пазухой» означает «на груди под одеждой»."]},{"author":"Б. Иомдин","question":"Вот отрывок из «Алисы в стране чудес» Л. Кэрролла в переводе Н. Демуровой:\n«От <em>перца</em>, видно, и начинают всем <em>перечить</em>… Алиса очень обрадовалась, что открыла новое правило. — От <em>уксуса</em> — <em>куксятся</em>, — продолжала она задумчиво,\n— от <em>горчицы</em> — <em>огорчаются</em>, от <em>лука</em> — <em>лукавят</em>, от <em>вина</em> — <em>винятся</em>…» А в какой из этих пар слова действительно произошли от одного корня?","choices":["<em>перец — перечить</em>","<em>уксус</em> — <em>кукситься</em>","<em>горчица — огорчаться</em>","<em>лук</em> — <em>лукавить</em>","<em>вино — виниться</em><strong>.</strong>"],"key":"В","review":["Алиса ищет родство слов","Для общего корня одного созвучия мало. Например, «виниться» относится к вине, то есть проступку, а «вино» — напиток.","Горчица горькая, а «огорчаться» — испытывать горечь от неприятности. Слова «горчица» и «огорчаться» исторически связаны с «горький»."]},{"author":"П. Аркадьев","question":"В каком из глаголов приставка <em>по-</em> употреблена не в том же значении, что в остальных?","choices":["<em>побегать</em>","<em>поспать</em>","<em>поплыть</em>","<em>поиграть</em>","<em>полежать</em>."],"key":"В","review":["Что добавляет «по-»?","Подставь «некоторое время». Так можно побегать, поспать, поиграть и полежать: действие длится какое-то время.","«Поплыть» — начать плыть, например «оттолкнулся от берега и поплыл». Здесь «по-» обозначает начало, поэтому этот вариант выделяется."]},{"author":"И. Рубанов","question":"<em>Плохая мне досталась ракетка, воланчик в ней всё время ...</em>","choices":["<em>застреёт</em>","<em>застряёт</em>","<em>застрёвывает</em>","<em>застревает</em>","<em>застрявает</em>."],"key":"Г","review":["Что делает воланчик?","Слова «всё время» подсказывают повторяющееся действие. Для него подходит начальная форма «застревать».","«Воланчик что делает?» — «застревает». Сохраняем гласную е из слова «застревать»."]},{"author":"О. Шеманаева","question":"Даны предложения из повести А. Гайдара «Голубая чашка».\n1. <em>Прогрохотал в гараж колхозный грузовик.</em>\n2. <em>Пропела в поле военная труба.</em>\n3. <em>Прогремел на север далёкий поезд.</em>\n4. <em>С криком промелькнула поперёк неба испуганная галка.</em>\nВ каких из этих предложений сказуемое обозначает перемещение?","choices":["только в 4","во всех, кроме 2","только в 3 и 4","только в 1 и 4","ни в каких."],"key":"Б","review":["Что перемещается?","Найди слова о направлении. Грузовик движется «в гараж», поезд — «на север», галка — «поперёк неба». Их глаголы передают перемещение.","Труба «пропела в поле», то есть прозвучала там. Передвижение обозначено в предложениях 1, 3 и 4."]},{"author":"И. Рубанов","question":"Когда человек быстро куда-то мчится, принято говорить, что он <em>бежит</em>:","choices":["<em>стремглав голову</em>","<em>сломя голову</em>","<em>стремя голову</em>","<em>сорвав голову</em>","<em>забыв голову</em>."],"key":"Б","review":["Как сказать о быстром беге?","Продолжи знакомый оборот «бежать … голову». Он рисует настолько быстрый бег, что будто можно упасть и разбиться.","Устойчивый вариант — «сломя голову». «Стремглав» тоже значит «быстро», но употребляется само по себе: «бежать стремглав»."]},{"author":"И. Иткин","question":"Какое из этих слов устроено не так, как остальные?","choices":["<em>борьба</em>","<em>гурьба</em>","<em>косьба</em>","<em>стрельба</em>","<em>ходьба</em>."],"key":"Б","review":["Пять слов на -ьба","Подбери глаголы к существительным. Борьба — от «бороться», косьба — от «косить», стрельба — от «стрелять», ходьба — от «ходить».","Во всех четырёх случаях существительное называет действие. «Гурьба» — толпа людей, слово с корнем «гурьб-», устроенное иначе."]},{"author":"О. Шеманаева","question":"<em>Докучать</em> означает:","choices":["‘скучать’","‘поучать’","‘надоедать’","‘добавлять’","‘требовать’."],"key":"В","review":["Когда тебе докучают","Представь, что кто-то снова и снова задаёт один вопрос и мешает тебе. Можно попросить его не докучать тебе этим вопросом.","Поменяй слово в просьбе: «не надоедай мне этим вопросом». Смысл сохранился, поэтому «докучать» значит «надоедать»."]},{"author":"Е. Муравенко","question":"Найдите слово, из которого можно получить новое слово, написав сначала второй слог, а потом первый.","choices":["<em>актёр</em>","<em>тополь</em>","<em>марка</em>","<em>банка</em>","<em>парта</em>."],"key":"Г","review":["Слоги поменялись местами","Попробуй разделить слова на слоги и прочитать задом наперёд именно слоги, сохраняя порядок букв внутри каждого. Например, «мар-ка» превращается в «ка-мар».","Из «бан-ка» получается «ка-бан». «Кабан» — название животного, поэтому подходит слово «банка»."]},{"author":"Б. Иомдин","question":"Рассмотрим слова:\n1) <em>легендарный</em>, 2) <em>мифический</em>, 3) <em>мифологический.</em>\nКакие из них могут означать ‘знаменитый, прославленный’?","choices":["1","2","3","1 и 2","все."],"key":"А","review":["Знаменитый или мифический?","Подставь слова к имени известного человека. «Легендарный спортсмен» привычно означает спортсмена, о котором много знают и рассказывают.","«Мифический» значит «существующий в мифе или вымысле», «мифологический» — «связанный с мифологией». Значение «прославленный» подходит только к «легендарный»."]},{"author":"Л. Фёдорова","question":"Седьмая вода на киселе — это:","choices":["компот","сказочный родник","зелье","самый далёкий из известных предков","какой-то дальний родственник."],"key":"Д","review":["Вода на киселе","В устойчивом выражении «седьмая вода» передаёт идею чего-то настолько далёкого, что связь едва заметна.","Так называют дальнего родственника, например того, с кем у семьи есть общий предок, но родство очень отдалённое."]},{"author":"Е. Муравенко","question":"<em>Сегодня мы говорили …</em> Как нужно продолжить фразу, чтобы её можно было понять только одним способом?","choices":["<em>о математике</em>","<em>о физике</em>","<em>о химике</em>","<em>о технике</em>","<em>о механике</em>."],"key":"В","review":["О чём говорили?","Проверь, может ли одна форма быть названием дела и человека. Математика, физика, техника и механика дают «о математике», «о физике», «о технике», «о механике», как и названия специалистов.","Наука называется «химия», и о ней говорят «о химии». Поэтому «о химике» можно понять только как разговор о человеке."]},{"author":"П. Аркадьев","question":"Какое слово не является однокоренным со всеми остальными?","choices":["<em>речь</em>","<em>нарекание</em>","<em>прорицатель</em>","<em>речка</em>","<em>изречение</em>."],"key":"Г","review":["Речь и похожие корни","Свяжи слова со смыслом: речь — то, что произносят, изречение — высказанная мысль, прорицатель возвещает будущее, нарекание выражают словами. Здесь встречаются варианты корня реч-, рек-, риц-.","Речка — маленькая река. Корень похож по буквам, но связан с водоёмом, поэтому «речка» выпадает."]},{"author":"Л. Фёдорова","question":"Сколько всего звонких согласных звуков в скороговорке:\n<em>Цапля чахла, цапля сохла, цапля сдохла</em>?","choices":["11","10","8","7","4."],"key":"В","review":["Звонкие в скороговорке","Отметь звонкие согласные, которые слышишь. В трёх словах «цапля» по одному [л’], а в «чахла» и «сохла» — по одному [л].","В «сдохла» слышны [з], [д] и [л]: перед д звук с становится звонким. Всего 3 + 1 + 1 + 3 = 8."]},{"author":"Е. Ренковская","question":"Даны слова и словосочетания на языке хинди в упрощённой транскрипции и их переводы на русский язык: бандар лог — <em>обезьяний народ</em>; багхера: — <em>пантера</em>; шер — <em>тигр</em>. Попробуйте догадаться, как на языке хинди будет звучать «медведь». (Двоеточие обозначает долготу гласной. Хинди — один из государственных языков Индии.)","choices":["кутта:","чу:ха:","кхаргош","кхаччар","бха:лу:."],"key":"Д","review":["Медведь на языке хинди","Вспомни персонажей «Книги джунглей»: там есть обезьяны Бандар-логи, пантера Багира и тигр Шер-Хан. Их имена похожи на данные слова.","Медведя из той же книги зовут Балу. Из вариантов этому имени соответствует «бха:лу:», по-хинди «медведь»."]},{"author":"Л. Фёдорова","question":"...Раздался ужасный треск, кувшин разбился, и комната наполнилась дымом. Али без чувств упал навзничь, Рашид, теряя сознание, повалился ничком, Хасан и Абдуррахман с воплями пали ниц. Когда дым рассеялся, все оставались в тех же позах. Чьё лицо (чьи лица) увидел джинн?","choices":["Хасана и Абдуррахмана","Али","Рашида","Рашида и Али","Хасана, Абдуррахмана и Рашида."],"key":"Б","review":["Кого увидел джинн?","Проверь положение каждого. «Ничком» и «ниц» означают «лицом вниз», так упали Рашид, Хасан и Абдуррахман.","«Навзничь» — на спину, лицом вверх. Так упал Али, и только его лицо было видно."]},{"author":"Е. Холодова","question":"Коля, Аня и Миша прочитали в учебнике такое задание:\n«Измени окончание слова <em>стол</em> так, чтобы это слово можно было перенести двумя способами». Коля написал <em>столовая</em>, Аня –– <em>столов</em>, Миша — <em>столики</em>. Кто из них справился с заданием?","choices":["только Коля","только Аня","только Миша","Коля и Миша","никто."],"key":"Д","review":["Окончание слова «стол»","В «столовая» и «столики» изменили не только окончание, но и само слово. Аня взяла форму того же слова «столов».","У «столов» только перенос «сто-лов». При «стол-ов» гласная отрывается от предшествующей согласной л, а у «ст-олов» слева нет гласной. Задание не выполнил никто."]},{"author":"Л. Фёдорова","question":"Во французском языке часто дают прозвища и шутливые наименования, составленные как сложные слова. В ответах даны пять таких сложных слов (слова, из которых они составлены, переведены на русский). Вот переводы четырёх из них (в перепутанном порядке): <em>подмастерье, мот, рассыльный, глашатай</em>. А ещё одно слово обозначает известного сказочного героя. Найдите это слово.","choices":["‘расколи-орешек’","‘перепрыгни-ручей’","‘неси-слово’","‘лови-наука’","‘проешь-всё’."],"key":"А","review":["Сказочный герой по-французски","Представь, чем занимается «расколи-орешек». Так можно назвать того, кто щёлкает орехи и раскалывает скорлупу.","Это Щелкунчик — сказочный герой. Другие названия относятся к людям по их привычке или делу, например «перепрыгни-ручей» подходит расторопному посыльному."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
